// OperationLogStats defines model for OperationLogStats.
type OperationLogStats struct {
	DailyStats []struct {
		AvgMs        *float32 `json:"avgMs"`
		Count        int      `json:"count"`
		Date         string   `json:"date"`
		FailCount    int      `json:"failCount"`
		SuccessCount int      `json:"successCount"`
	} `json:"dailyStats"`

	// DurationHistogram 耗时区间分布
	DurationHistogram []struct {
		Bucket string `json:"bucket"`
		Count  int    `json:"count"`
	} `json:"durationHistogram"`

	// FailModuleStats 失败热点模块 Top（responseCode >= 400）
	FailModuleStats []struct {
		Count  int    `json:"count"`
		Module string `json:"module"`
	} `json:"failModuleStats"`
	HourlyStats []struct {
		Count int `json:"count"`
		Hour  int `json:"hour"`
	} `json:"hourlyStats"`
	MethodStats []struct {
		Count  int    `json:"count"`
		Method string `json:"method"`
	} `json:"methodStats"`
	ModuleStats []struct {
		Count  int    `json:"count"`
		Module string `json:"module"`
	} `json:"moduleStats"`
	ModuleTimingStats []struct {
		AvgMs  float32 `json:"avgMs"`
		Count  int     `json:"count"`
		MaxMs  float32 `json:"maxMs"`
		Module string  `json:"module"`
	} `json:"moduleTimingStats"`

	// PrevSummary 上一周期（相同天数）汇总，用于环比
	PrevSummary struct {
		AvgDurationMs *float32 `json:"avgDurationMs"`
		FailCount     int      `json:"failCount"`
		SuccessCount  int      `json:"successCount"`
		Total         int      `json:"total"`
		UniqueUsers   int      `json:"uniqueUsers"`
	} `json:"prevSummary"`

	// SlowPaths 慢接口 Top（按平均耗时）
	SlowPaths []struct {
		AvgMs float32 `json:"avgMs"`
		Count int     `json:"count"`
		MaxMs float32 `json:"maxMs"`
		Path  string  `json:"path"`
	} `json:"slowPaths"`

	// StatusClassStats 响应状态码分布（按 2xx/3xx/4xx/5xx 归类）
	StatusClassStats []struct {
		Count       int    `json:"count"`
		StatusClass string `json:"statusClass"`
	} `json:"statusClassStats"`
	Summary struct {
		AvgDurationMs *float32 `json:"avgDurationMs"`
		FailCount     int      `json:"failCount"`

		// P50DurationMs 耗时分位数（基于有耗时记录的请求）
		P50DurationMs *float32 `json:"p50DurationMs"`
		P95DurationMs *float32 `json:"p95DurationMs"`
		P99DurationMs *float32 `json:"p99DurationMs"`
		SuccessCount  int      `json:"successCount"`
		Total         int      `json:"total"`
		UniqueUsers   int      `json:"uniqueUsers"`
	} `json:"summary"`

	// UserModuleFlows 用户 → 模块 操作流向（桑基图数据源）
	UserModuleFlows []struct {
		Count    int     `json:"count"`
		Module   string  `json:"module"`
		Nickname *string `json:"nickname,omitempty"`
		Username string  `json:"username"`
	} `json:"userModuleFlows"`
	UserStats []struct {
		Count    int     `json:"count"`
		Nickname *string `json:"nickname,omitempty"`
		Username string  `json:"username"`
	} `json:"userStats"`
}

